## --- test set generated by autotest_score
test_that("[autotest_score]: S3 method score works as expected for ChiSquare distribution", {
    ## Incorrect use (sanity checks)
    expect_error(score(d1),                           regexp = "argument \"x\" is missing")
    expect_error(score(dn, seq_len(length(dn) + 1)),  regexp = "parameter lengths do not match")
    expect_error(score(d1, 1, which = 1),                info = "invalid argument for which should throw error")
    expect_error(score(d1, 1, which = "foo"),            info = "invalid argument for which should throw error")

    ## Checking structure of returned object (not values)
    expect_silent(x <- score(dn, 1, drop = FALSE))
    expect_true(is.matrix(x) && is.numeric(x),              info = "expected numeric matrix")
    expect_identical(dimnames(x), list(names(dn), "df"), info = "incorrect dimnames or dimension")

    ## Check calculating single score with default drop = TRUE; unnamed
    for (d in "df") {
        expect_silent(x <- score(dx, 1, which = d))
        expect_true(is.atomic(x) && is.numeric(x),          info = "expected numeric vector return")
        expect_identical(length(x), length(dn),             info = "return has incorrect length")
        expect_null(names(x),                               info = "expected unnamed vector to be returned")
    }

    ## Check calculating single score with default drop = TRUE; named
    for (d in "df") {
        expect_silent(x <- score(dn, 1, which = d))
        expect_true(is.atomic(x) && is.numeric(x),          info = "expected numeric vector return")
        expect_identical(length(x), length(dn),             info = "return has incorrect length")
        expect_identical(names(x), names(dn),               info = "expected named vector to be returned")
    }
});


